/**
 * Quality guard for the full TOEIC test bank (toeic_web_app/toeic_full_tests.json).
 *
 * The bank is generated by build_toeic_full.py from ALL_TOEIC_TESTS/*.json
 * (full exams: 200 questions, parts 1-7). Part 1 picture questions are not
 * implemented, so every test keeps parts 2-7 with 194 questions. This test
 * freezes the generated shape with zero
 * tolerance: every question needs exactly one key among its options, no
 * duplicates, listening items carry a transcript, reading passages carry
 * EN/KO content.
 */
import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const bankPath = path.join(root, 'toeic_web_app/toeic_full_tests.json');
const bank = JSON.parse(fs.readFileSync(bankPath, 'utf8'));

const norm = (s) => String(s ?? '').replace(/\s+/g, ' ').trim().toLowerCase();
const EXPECTED_PARTS = [2, 3, 4, 5, 6, 7];
const EXPECTED_QUESTIONS = 194; // 200 minus the 6 picture questions

describe('Full TOEIC test bank quality', () => {
  it('ships at least one test with parts 2-7', () => {
    expect(bank.tests.length, 'at least one test in the bank').toBeGreaterThan(0);
    for (const test of bank.tests) {
      expect(typeof test.id, `test ${test.id} has an id`).toBe('string');
      expect(test.name, `test ${test.id} has a name`).toBeTruthy();
      const parts = test.parts.map((p) => p.part);
      expect(parts, `test ${test.id} keeps parts 2-7`).toEqual(EXPECTED_PARTS);
    }
  });

  it('has exactly 194 questions per test', () => {
    for (const test of bank.tests) {
      const n = test.parts.reduce(
        (sum, p) => sum + p.items.reduce((s, it) => s + it.questions.length, 0), 0);
      expect(n, `test ${test.id} question count`).toBe(EXPECTED_QUESTIONS);
    }
  });

  it('marks its key exactly once per question', () => {
    const offenders = [];
    for (const test of bank.tests) {
      for (const p of test.parts) {
        for (const it of p.items) {
          for (const q of it.questions) {
            if (!q.options.includes(q.correct)) offenders.push(`${test.id} p${p.part}: ${q.question.slice(0, 40)}`);
            if (q.options.filter((o) => norm(o) === norm(q.correct)).length !== 1) {
              offenders.push(`${test.id} p${p.part}: ambiguous key "${q.correct}"`);
            }
          }
        }
      }
    }
    expect(offenders, 'question(s) without exactly one matching key').toEqual([]);
  });

  it('accepts only distinct, visible alternatives and keeps a primary key', () => {
    let ambiguous = 0;
    for (const test of bank.tests) {
      for (const part of test.parts) {
        for (const item of part.items) {
          for (const q of item.questions) {
            if (!q.acceptedAnswers) continue;
            ambiguous += 1;
            expect(q.acceptedAnswers.length).toBeGreaterThanOrEqual(2);
            expect(new Set(q.acceptedAnswers).size).toBe(q.acceptedAnswers.length);
            expect(q.acceptedAnswers).toContain(q.correct);
            for (const answer of q.acceptedAnswers) expect(q.options).toContain(answer);
            expect(Boolean(q.unscored)).toBe(q.acceptedAnswers.length === q.options.length);
            expect(q.explanation.en).toBeTruthy();
            expect(q.explanation.ko).toMatch(/[가-힣]/);
          }
        }
      }
    }
    expect(ambiguous).toBeGreaterThan(5);
  });

  it('contains no duplicate questions inside a test', () => {
    const offenders = [];
    for (const test of bank.tests) {
      const seen = new Set();
      for (const p of test.parts) {
        for (const it of p.items) {
          for (const q of it.questions) {
            const key = `${norm(q.question)}||${q.options.map(norm).sort().join('|')}`;
            if (seen.has(key)) offenders.push(`${test.id} p${p.part}: duplicate of an earlier question`);
            else seen.add(key);
          }
        }
      }
    }
    expect(offenders, 'duplicate question(s) in the bank').toEqual([]);
  });

  it('keeps every question well formed', () => {
    for (const test of bank.tests) {
      for (const p of test.parts) {
        for (const it of p.items) {
          for (const q of it.questions) {
            expect(q.question, `test ${test.id} p${p.part}`).toBeTruthy();
            expect(q.options.length, `test ${test.id} p${p.part} needs 2+ options`).toBeGreaterThanOrEqual(2);
            expect(q.options.every((o) => o && o.trim() !== ''), `test ${test.id} p${p.part} empty option`).toBe(true);
            expect(q.options.every((o) => !/^\{.*\}$/.test(o) && !/^key:/i.test(o)),
              `test ${test.id} p${p.part} has a raw key marker left`).toBe(true);
          }
        }
      }
    }
  });

  it('keeps the expected option counts, apart from two documented source duplicates', () => {
    const known = new Set([
      'new_economy_2018_test_10:5:0:0',
      'new_economy_2018_test_10:6:3:1',
    ]);
    const seen = new Set();
    for (const test of bank.tests) {
      for (const part of test.parts) {
        for (const item of part.items) {
          item.questions.forEach((q, index) => {
            const key = `${test.id}:${part.part}:${item.itemIndex}:${index}`;
            const expected = part.part === 2 || known.has(key) ? 3 : 4;
            expect(q.options.length, key).toBe(expected);
            if (known.has(key)) seen.add(key);
          });
        }
      }
    }
    expect(seen).toEqual(known);
  });

  it('removes editorial markup while retaining distinct speaker turns', () => {
    for (const test of bank.tests) {
      for (const part of test.parts.filter((p) => p.part === 3 || p.part === 4)) {
        for (const item of part.items) {
          const label = `${test.id} p${part.part} item ${item.itemIndex}`;
          expect(item.audio, label).not.toMatch(/\(\s*\d+\s*\.?\s*\)|[[\]{}|]/);
          if (part.part === 3) expect(item.turns?.length, label).toBeGreaterThanOrEqual(2);
          if (item.turns?.length) {
            expect(item.turns.map((turn) => turn.text).join(' '), label).toBe(item.audio);
            for (const turn of item.turns) {
              expect(turn.speaker, label).toMatch(/^[MW][12]?$/);
              expect(turn.text, label).toBeTruthy();
            }
          }
        }
      }
    }
  });

  it('keeps the English choices and keys for the three reported Part 2 items', () => {
    const test = bank.tests.find((entry) => entry.id === 'new_economy_2018_test_05');
    const part = test.parts.find((entry) => entry.part === 2);
    const samples = [
      [11, ['It’s black and white', 'This is not mine', 'No problem. Go ahead.'], 'No problem. Go ahead.'],
      [16, ['At the local community center', 'I’ve been assigned the role', 'Oh, so did I'], 'Oh, so did I'],
      [19, ['New login information', 'For the corporate function', 'It’s being repaired'], 'It’s being repaired'],
    ];
    for (const [number, options, correct] of samples) {
      const question = part.items[number - 7].questions[0];
      expect(question.options).toEqual(options);
      expect(question.correct).toBe(correct);
    }
  });

  it('keeps reviewed passages, speaker roles and answers consistent', () => {
    const getItem = (id, part, index) => bank.tests.find((test) => test.id === id)
      .parts.find((entry) => entry.part === part).items[index];
    const bus = getItem('new_economy_2018_test_02', 4, 2);
    expect(bus.audio).toContain('an hour later');
    expect(bus.audio).toContain('5:00 P.M.');
    expect(bus.questions[1].question).toContain('expected to arrive');
    expect(bus.questions[1].correct).toBe('6:00 P.M');

    const nutrition = getItem('new_economy_2018_test_05', 3, 12);
    expect(nutrition.turns.at(-1).speaker).toBe('W');
    expect(nutrition.turns.at(-1).text).toContain('suggest');
    expect(nutrition.questions[1].correct).toBe('Sugar');
    expect(nutrition.graphic.html).toContain('Sugar');

    const delivery = getItem('new_economy_2018_test_08', 3, 8);
    expect(delivery.turns.at(-1).speaker).toBe('W');
    expect(delivery.turns.at(-1).text).toContain('cell phone number');
    expect(delivery.questions[2].correct).toBe('His cell phone number');
  });

  it('retains every source listening graphic and local image', () => {
    let images = 0;
    let descriptions = 0;
    for (const test of bank.tests) {
      const source = JSON.parse(fs.readFileSync(path.join(root, 'ALL_TOEIC_TESTS', `${test.id}.json`), 'utf8'));
      for (const part of test.parts.filter((entry) => entry.part === 3 || entry.part === 4)) {
        for (const item of part.items) {
          const raw = source[`part${part.part}`][item.itemIndex];
          if (raw.image) {
            images += 1;
            expect(item.graphic?.image, test.id).toMatch(new RegExp(`^full-toeic-graphics/${raw.image}\\.(?:png|jpe?g)$`));
            expect(fs.existsSync(path.join(root, 'public', item.graphic.image)), test.id).toBe(true);
          } else {
            expect(item.graphic?.image).toBeUndefined();
          }
          if (raw.description?.trim()) {
            descriptions += 1;
            const expected = test.id === 'new_economy_2018_test_04' && part.part === 3 && item.itemIndex === 10
              ? raw.description.trim().replace('Barrel Buts', 'Barrel Nuts') : raw.description.trim();
            expect(item.graphic?.html, test.id).toBe(expected);
          } else {
            expect(item.graphic?.html).toBeUndefined();
          }
        }
      }
    }
    expect({ images, descriptions }).toEqual({ images: 43, descriptions: 25 });
  });

  it('gives listening parts a transcript for speechSynthesis', () => {
    const offenders = [];
    for (const test of bank.tests) {
      for (const p of test.parts.filter((x) => x.type === 'listening')) {
        for (const it of p.items) {
          if (!it.audio || it.audio.trim() === '') {
            offenders.push(`${test.id} p${p.part} item ${it.itemIndex}: no transcript`);
          }
          if (!it.questions.length) {
            offenders.push(`${test.id} p${p.part} item ${it.itemIndex}: no questions`);
          }
        }
      }
    }
    expect(offenders, 'listening item(s) without audio').toEqual([]);
  });

  it('keeps listening item question counts stable (part 2: 1, parts 3-4: 3)', () => {
    const expected = { 2: 1, 3: 3, 4: 3 };
    for (const test of bank.tests) {
      for (const p of test.parts.filter((x) => x.type === 'listening')) {
        for (const it of p.items) {
          expect(it.questions.length, `${test.id} p${p.part} item ${it.itemIndex}`).toBe(expected[p.part]);
        }
      }
    }
  });

  it('keeps reading passages and reports unavailable translations honestly', () => {
    // The source has gaps; English-only or answer-only text is not Korean
    // reasoning. Freeze the exact exceptions so new omissions cannot hide.
    const expectedMissingEn = [
      'new_economy_2018_test_02:7:9:3',
      'new_economy_2018_test_02:7:11:0', 'new_economy_2018_test_02:7:12:0',
      'new_economy_2018_test_02:7:13:2',
      'new_economy_2018_test_02:7:14:1', 'new_economy_2018_test_05:7:9:3',
      'new_economy_2018_test_08:6:0:3', 'new_economy_2018_test_10:6:0:3',
    ];
    const expectedMissingKo = [
      'hacker_new_toeic_test_02:7:1:0', 'hacker_new_toeic_test_02:7:5:2',
      'hacker_new_toeic_test_02:7:6:2', 'hacker_new_toeic_test_02:7:6:3',
      'hacker_new_toeic_test_02:7:9:2', 'hacker_new_toeic_test_02:7:9:3',
      'hacker_new_toeic_test_02:7:10:0', 'hacker_new_toeic_test_02:7:10:1',
      'hacker_new_toeic_test_02:7:10:2', 'hacker_new_toeic_test_02:7:10:3',
      'hacker_new_toeic_test_02:7:11:0', 'hacker_new_toeic_test_02:7:11:1',
      'hacker_new_toeic_test_02:7:11:3', 'hacker_new_toeic_test_02:7:12:0',
      'hacker_new_toeic_test_02:7:13:2', 'hacker_new_toeic_test_02:7:14:0',
      'hacker_new_toeic_test_02:7:14:4', 'new_economy_2018_test_09:6:1:0',
      'new_economy_2018_test_09:7:5:2', 'new_economy_2018_test_09:7:6:0',
      'new_economy_2018_test_09:7:8:2', 'new_economy_2018_test_09:7:12:0',
      'new_economy_2018_test_10:6:0:3', 'new_economy_2018_test_10:6:1:3',
      'new_economy_2018_test_10:6:2:0',
    ];
    const missingEn = [], missingKo = [];
    for (const test of bank.tests) {
      for (const p of test.parts.filter((x) => x.type === 'reading')) {
        for (const it of p.items) {
          const label = `${test.id} p${p.part} item ${it.itemIndex}`;
          if (p.part >= 6) {
            expect(it.description?.trim(), label).toBeTruthy();
            if (it.hasKoPassage) expect(it.descriptionKo, label).toMatch(/[가-힣]/);
          }
          const allHaveEnglish = it.questions.every((q) => q.explanation?.en?.trim());
          expect(it.hasEnExplanation, label).toBe(allHaveEnglish);
          it.questions.forEach((q, index) => {
            const key = `${test.id}:${p.part}:${it.itemIndex}:${index}`;
            expect(typeof q.explanation?.en, key).toBe('string');
            expect(typeof q.explanation?.ko, key).toBe('string');
            expect(q.explanation.en, key).not.toMatch(/[가-힣]/);
            if (!q.explanation.en.trim()) missingEn.push(key);
            if (!q.explanation.ko.trim()) missingKo.push(key);
            else expect(q.explanation.ko, key).toMatch(/[가-힣]/);
          });
        }
      }
    }
    expect(missingEn.sort()).toEqual(expectedMissingEn.sort());
    expect(missingKo.sort()).toEqual(expectedMissingKo.sort());
  });

  it('wraps part 6 blanks in highlightable spans', () => {
    for (const test of bank.tests) {
      for (const p of test.parts.filter((x) => x.part === 6)) {
        for (const it of p.items) {
          const blanks = it.description.match(/class="toeic-blank" data-blank="\d+"/g) || [];
          expect(blanks.length, `test ${test.id} p6 item ${it.itemIndex} blank spans`)
            .toBe(it.questions.length);
        }
      }
    }
  });
});
